 const values=tera&&tera!=='stellar'?[tera]:mon?.currentTypes?.length?mon.currentTypes:mon?.types||[];
 const types=[...new Set((values as string[]).filter(Boolean).map(raw=>Object.keys(typeLabels).find(key=>key===raw.toLowerCase()||typeLabels[key]===raw)||raw.toLowerCase()))];
 return types.length?<span className="bs-type-symbols" aria-label="현재 방어 타입">{types.map(type=><TypeSymbol key={type} type={type} label={typeLabels[type]||type}/>)}</span>:null;
