function ExperienceBar({mon}:{mon:any}){if(!Number.isFinite(mon?.experience)||!Number.isFinite(mon?.level)||!Number.isFinite(mon?.rogueExperienceToNext))return null;const needed=mon.rogueExperienceToNext,value=needed?Math.max(0,Math.min(needed,mon.experience)):0,fraction=needed?value/needed:1;return <div className="bs-exp" role="meter" aria-label={mon.name+' 경험치'} aria-valuemin={0} aria-valuemax={needed||1} aria-valuenow={needed?value:1} title={needed?'다음 레벨까지 '+(needed-value)+' 경험치':'최대 레벨'}><span>EXP</span><i><b style={{transform:'scaleX('+fraction+')'}}/></i></div>;}
