function MoveCard({m,index,locked,selected,move,open,onDescription}:{m:any;index:number;locked:boolean;selected:boolean;move:(m:any)=>unknown;open:boolean;onDescription:(open:boolean)=>void}){
const unavailable=m.pp<=0?(m.disabledReason||'PP가 없습니다.'):m.disabled?(m.disabledReason||'지금 사용할 수 없습니다.'):'',tooltipId='bs-move-description-'+m.id+'-'+(m.slot??index);return <div className="bs-move-wrap" data-detail-open={open||undefined} onPointerLeave={event=>{if(event.pointerType==='mouse')onDescription(false)}} onBlur={event=>{if(!event.currentTarget.contains(event.relatedTarget))onDescription(false)}}>
<button aria-describedby={tooltipId} data-command-primary data-roving="move" className={`bs-move ${selected?'selected':''}`} data-type={m.typeKey||'normal'} disabled={locked||m.disabled||m.pp<=0} aria-label={`${index+1}. ${m.name}, ${m.type||typeLabels[m.typeKey]||''}, PP ${m.pp}/${m.maxPp}, ${unavailable||impactLabel(m)}`} onPointerEnter={event=>{if(event.pointerType==='mouse'&&window.matchMedia('(hover: hover) and (pointer: fine)').matches)onDescription(true)}} onClick={()=>move(m)}><span className="bs-move-cursor" aria-hidden="true">▶</span><span className="bs-move-name"><small>{index+1}</small><b>{m.name}</b></span><TypeSymbol type={m.typeKey||'normal'} label={m.type||typeLabels[m.typeKey]||'노말'}/><span className="bs-move-compact-pp">PP {m.pp}/{m.maxPp}</span><span className="bs-move-stats"><span>{m.category==='Status'||m.category==='status'?'변화':`위력 ${m.power===0?'변동':m.power??'—'}`} · 명중 {m.accuracy===true?'—':m.accuracy??'—'}</span><b>PP {m.pp}<small>/{m.maxPp}</small></b></span><span className={`bs-effectiveness ${m.effectivenessByTarget?.length>1?'':Number(m.effectiveness)>1?'strong':m.effectiveness!=null&&Number(m.effectiveness)<1?'weak':''}`} title="타입 기준 예상 상성. 특성과 물건은 서버 판정에 반영됩니다.">{!unavailable&&String(m.category||'').toLowerCase()!=='status'&&<small>타입 기준 · </small>}{unavailable||impactLabel(m)}</span></button>
<button type="button" className="bs-move-info" aria-label={m.name+' 기술 설명'} aria-expanded={open} aria-controls={tooltipId} onClick={()=>onDescription(!open)}>i</button><div className="bs-move-tooltip" id={tooltipId} role="tooltip" aria-hidden={!open}><b>{m.name}</b>{unavailable&&<p className="bs-move-unavailable">{unavailable}</p>}<p>{m.description||'기술 설명을 불러오지 못했습니다.'}</p><small>{m.targetLabel||'대상 1마리'} · 우선도 {m.priority??0}{m.contact?' · 접촉 기술':''} · {m.category==='Status'||m.category==='status'?'변화':`위력 ${m.power===0?'변동':m.power??'—'}`} · 명중 {m.accuracy===true?'—':m.accuracy??'—'} · {impactLabel(m)}</small></div></div>;}

const ballAtlasY:Record<string,number>={pokeball:210,greatball:174,ultraball:234,rogueball:222,masterball:198};
function BallIcon({id,fallback}:{id:string;fallback?:string}){const [failed,setFailed]=useState<string|null>(null),y=ballAtlasY[id];return y===undefined?(fallback&&failed!==fallback?<img src={fallback} width="36" height="36" alt="" onError={()=>setFailed(fallback)}/>:<CircleDot size={30} aria-hidden="true"/>):<span className="bs-ball-atlas" aria-hidden="true" style={{backgroundPosition:`0 -${y*3}px`}}/>;}
